// Verify the LEVELS embedded in sokoban.html match the validated Microban picks,
// and that each one parses cleanly through the shipped engine.
import { readFile } from 'node:fs/promises';
import assert from 'node:assert/strict';

// --- levels as generated by tools/build-levels.mjs selection logic
const ref = await readFile(new URL('./ref-levels2.js', import.meta.url), 'utf8');
const rm = ref.match(/const LEVELS = \[([\s\S]*?)\n\];/);
const ALL = new Function(`return [${rm[1]}];`)();

function stats(text) {
  const flat = text.split('\n').join('');
  const c = (re) => (flat.match(re) || []).length;
  return { players: c(/[@+]/g), boxes: c(/[$*]/g), goals: c(/[.*+]/g) };
}

const expected = [];
for (let i = 0; i < ALL.length; i++) {
  const s = stats(ALL[i]);
  if (s.players === 1 && s.boxes === s.goals) expected.push(ALL[i]);
}

// --- levels actually embedded in the game
const html = await readFile(new URL('../sokoban.html', import.meta.url), 'utf8');
const lm = html.match(/const LEVELS = \[([\s\S]*?)\n  \];/);
assert.ok(lm, 'LEVELS block not found in sokoban.html');
const embedded = new Function(`return [${lm[1]}];`)();

assert.equal(embedded.length, expected.length, `level count: got ${embedded.length}, want ${expected.length}`);
let diffs = 0;
embedded.forEach((lvl, i) => {
  if (lvl !== expected[i]) {
    diffs++;
    console.log(`\nMISMATCH at level ${i + 1}`);
    console.log('--- embedded ---\n' + lvl);
    console.log('--- expected ---\n' + expected[i]);
  }
});

// --- every embedded level must be playable by the shipped engine
const engineSrc = html.match(/<script id="engine">([\s\S]*?)<\/script>/)[1];
const Sokoban = new Function(`${engineSrc}\n;return globalThis.Sokoban;`)();
embedded.forEach((lvl, i) => {
  const g = Sokoban.createGame(lvl);
  assert.equal(g.boxes.length, g.level.goals.flat().filter(Boolean).length, `level ${i + 1}: boxes vs goals`);
  assert.ok(!g.isWon(), `level ${i + 1} must not start already won`);
});

console.log(diffs ? `\nFAILED: ${diffs} mismatched levels` : `OK: ${embedded.length} levels identical to reference, all parse & start unsolved`);
process.exitCode = diffs ? 1 : 0;
